REVOKE ALL ON FUNCTION public.delivery_event_context(),public.notify_delivery_event(),public.delivery_event_append_only(),public.validate_delivery_job_workflow(),public.is_active_delivery_rider(uuid,uuid) FROM PUBLIC,anon,authenticated;
ALTER TABLE public.delivery_job_events ADD COLUMN previous_rider_id uuid;
CREATE OR REPLACE FUNCTION public.notify_delivery_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.delivery_jobs; uid uuid; BEGIN IF NEW.action='note' THEN RETURN NEW; END IF; SELECT * INTO j FROM public.delivery_jobs WHERE id=NEW.job_id; FOR uid IN SELECT p.owner_id FROM public.pharmacies p WHERE p.id IN (j.pharmacy_id,j.buyer_pharmacy_id) AND p.owner_id IS NOT NULL UNION SELECT m.user_id FROM public.pharmacy_memberships m WHERE m.pharmacy_id IN (j.pharmacy_id,j.buyer_pharmacy_id) AND m.is_active=true AND m.employment_status='active' AND m.role IN ('manager','cashier','pharmacist','inventory_manager') UNION SELECT j.rider_id WHERE j.rider_id IS NOT NULL UNION SELECT NEW.previous_rider_id WHERE NEW.previous_rider_id IS NOT NULL UNION SELECT m.user_id FROM public.pharmacy_memberships m WHERE NEW.action IN ('created','reassign') AND m.pharmacy_id=j.pharmacy_id AND public.is_active_delivery_rider(j.pharmacy_id,m.user_id) LOOP PERFORM public.notify_user(uid,j.pharmacy_id,CASE WHEN NEW.action IN ('failed','cancel') THEN 'warning' ELSE 'info' END,'Delivery '||j.tracking_number,replace(NEW.action,'_',' ')||' · '||NEW.new_status,'/pharmacy?id='||j.pharmacy_id); END LOOP; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.delivery_exception(_job uuid,_action text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.delivery_jobs; target text; BEGIN SELECT * INTO j FROM public.delivery_jobs WHERE id=_job FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Delivery not found'; END IF; IF coalesce(trim(_reason),'')='' OR length(_reason)>500 THEN RAISE EXCEPTION 'Give an exception reason (max 500 characters)'; END IF; IF j.status IN ('delivered','cancelled','returned') THEN RAISE EXCEPTION 'Delivery already closed'; END IF; IF _action IN ('cancel','reassign') THEN IF NOT public.can_write_pharmacy(j.pharmacy_id,ARRAY['manager']::public.user_role[]) THEN RAISE EXCEPTION 'Only an authorized owner, manager or administrator may cancel or reassign'; END IF; IF _action='reassign' AND public.delivery_workflow_status(j.status) NOT IN ('in_process','pickup') THEN RAISE EXCEPTION 'Reassignment is only allowed before collection'; END IF; target:=CASE _action WHEN 'cancel' THEN 'cancelled' ELSE 'in_process' END; ELSE IF j.rider_id IS DISTINCT FROM auth.uid() OR NOT public.is_active_delivery_rider(j.pharmacy_id,auth.uid()) OR NOT public.pharmacy_has_plan_feature(j.pharmacy_id,'delivery') THEN RAISE EXCEPTION 'Only the assigned active rider may report delivery failure or return'; END IF; target:=CASE WHEN _action='failed' AND public.delivery_workflow_status(j.status) IN ('in_process','pickup','in_transit','arrived') THEN 'failed' WHEN _action='start_return' AND j.status='failed' THEN 'returning' WHEN _action='returned' AND j.status='returning' THEN 'returned' END; IF target IS NULL THEN RAISE EXCEPTION 'Invalid failure/return sequence'; END IF; END IF; UPDATE public.delivery_jobs SET status=target,exception_reason=trim(_reason),updated_at=now(),cancelled_at=CASE WHEN target='cancelled' THEN now() ELSE cancelled_at END,failed_at=CASE WHEN target='failed' THEN now() ELSE failed_at END,returned_at=CASE WHEN target='returned' THEN now() ELSE returned_at END,rider_id=CASE WHEN _action='reassign' THEN NULL ELSE rider_id END,assignment_state=CASE WHEN _action='reassign' THEN 'available' ELSE assignment_state END,accepted_at=CASE WHEN _action='reassign' THEN NULL ELSE accepted_at END,pickup_started_at=CASE WHEN _action='reassign' THEN NULL ELSE pickup_started_at END,pickup_arrived_at=CASE WHEN _action='reassign' THEN NULL ELSE pickup_arrived_at END WHERE id=_job; INSERT INTO public.delivery_job_events(job_id,status,actor_id,action,previous_status,new_status,note,previous_rider_id) VALUES(_job,target,auth.uid(),_action,j.status,target,trim(_reason),CASE WHEN _action='reassign' THEN j.rider_id END); END $$;
CREATE FUNCTION public.guard_new_delivery_plan() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.pharmacy_has_plan_feature(NEW.pharmacy_id,'delivery') THEN RAISE EXCEPTION 'Delivery creation requires an authenticated caller and eligible current plan'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_new_delivery_plan() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER guard_new_delivery_plan BEFORE INSERT ON public.delivery_jobs FOR EACH ROW EXECUTE FUNCTION public.guard_new_delivery_plan();